"use client";

/**
 * The composer, on the T3 prompt input (ADR-0013): an autosizing
 * textarea that sends on Enter, attachments by "+" / paste / drop when
 * `chatConfig.attachments` allows them, a model picker when the page
 * offers more than one, and a submit that becomes stop while a reply
 * streams. The draft is the thread's, so nothing typed is lost to a
 * model switch or a navigation.
 *
 * ArrowUp in an empty composer loads the last message the reader sent,
 * to edit and re-send — the shell habit a chat inherits.
 */

import { useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { toast } from "sonner";
import type { FileUIPart } from "ai";

import type { ChatModelOption } from "@intelligo-dev/chat/client";

import { ComposerMenu } from "@/components/ui/ai-composer-menu";
import { SpeechInput } from "@/components/ui/ai-speech-input";
import { useComposerMenu } from "@/hooks/use-composer-menu";

import {
  PromptInput,
  PromptInputActionAddAttachments,
  PromptInputActionMenu,
  PromptInputActionMenuContent,
  PromptInputActionMenuTrigger,
  PromptInputAttachment,
  PromptInputAttachments,
  PromptInputFooter,
  PromptInputSelect,
  PromptInputSelectContent,
  PromptInputSelectItem,
  PromptInputSelectTrigger,
  PromptInputSelectValue,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputTools,
  type PromptInputError,
} from "@/components/ui/ai-prompt-input";
import { chatConfig, type ChatMention } from "@/lib/chat-config";

interface ChatInputProps {
  conversationId: string;
  value: string;
  onChange: (value: string) => void;
  onSend: (text: string, files: FileUIPart[], mentions: ChatMention[]) => void;
  onStop: () => void;
  onEditLast?: () => void;
  isStreaming: boolean;
  /**
   * Stops the composer accepting a turn that will be refused — out of
   * credits, or behind a feature gate. The banner above says why; this
   * is what keeps someone from writing a paragraph into a request the
   * route has already told us it will reject.
   */
  disabled?: boolean;
  /** Placeholder to show instead of the usual one while disabled. */
  disabledPlaceholder?: string;
  models?: ChatModelOption[];
  modelId?: string;
  onModelChange?: (modelId: string) => void;
  autoFocus?: boolean;
  compact?: boolean;
}

const DEFAULT_UPLOAD_URL = "/api/chat/upload";

/** In `stored` mode a picked file uploads first; the message carries its app URL. */
async function upload(
  file: FileUIPart,
  uploadUrl: string
): Promise<FileUIPart> {
  const blob = await (await fetch(file.url)).blob();
  const form = new FormData();
  form.set("file", blob, file.filename ?? "file");
  const response = await fetch(uploadUrl, { method: "POST", body: form });
  if (!response.ok) throw new Error(`upload failed: ${response.status}`);
  const result = (await response.json()) as {
    url: string;
    mediaType: string;
    filename: string;
  };
  return {
    type: "file",
    url: result.url,
    mediaType: result.mediaType,
    filename: result.filename,
  };
}

export function ChatInput({
  conversationId,
  value,
  onChange,
  onSend,
  onStop,
  onEditLast,
  isStreaming,
  disabled = false,
  disabledPlaceholder,
  models = [],
  modelId,
  onModelChange,
  autoFocus = false,
  compact = false,
}: ChatInputProps) {
  const t = useTranslations("chat");
  const [uploading, setUploading] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const attachments = chatConfig.attachments;
  const placeholder =
    disabled && disabledPlaceholder
      ? disabledPlaceholder
      : t("input.placeholder");

  useEffect(() => {
    if (autoFocus) textareaRef.current?.focus();
  }, [autoFocus]);

  const menu = useComposerMenu({
    value,
    setValue: onChange,
    conversationId,
    send: (text) => onSend(text, [], []),
    textareaRef,
  });

  function reportError(error: PromptInputError) {
    if (error.code === "max_files") {
      toast.error(t("attachments.tooMany", { max: attachments?.maxFiles ?? 1 }));
    } else if (error.code === "max_file_size") {
      toast.error(t("attachments.tooLarge"));
    } else {
      toast.error(t("attachments.unsupported"));
    }
  }

  return (
    <div className={compact ? "bg-background p-3 pt-2" : "bg-background px-4 pt-2 pb-4"}>
      <PromptInput
        className={compact ? "w-full" : "mx-auto max-w-3xl"}
        accept={attachments?.accept.join(",")}
        multiple={(attachments?.maxFiles ?? 1) !== 1}
        maxFiles={attachments?.maxFiles}
        maxFileSize={attachments?.maxBytes}
        globalDrop={Boolean(attachments) && !compact}
        onError={reportError}
        onSubmit={async ({ text, files }) => {
          const trimmed = text.trim();
          if ((!trimmed && files.length === 0) || isStreaming || disabled) {
            return;
          }
          let parts = files;
          if (attachments?.mode === "stored" && files.length > 0) {
            setUploading(true);
            try {
              parts = await Promise.all(
                files.map((file) =>
                  upload(file, attachments.uploadUrl ?? DEFAULT_UPLOAD_URL)
                )
              );
            } catch {
              toast.error(t("attachments.uploadFailed"));
              throw new Error("upload failed");
            } finally {
              setUploading(false);
            }
          }
          onSend(trimmed, parts, menu.mentions);
          menu.clearPicked();
        }}
      >
        {attachments ? (
          <PromptInputAttachments>
            {(file) => (
              <PromptInputAttachment
                key={file.id}
                data={file}
                removeLabel={t("attachments.remove")}
              />
            )}
          </PromptInputAttachments>
        ) : null}
        <PromptInputTextarea
          ref={textareaRef}
          value={value}
          onChange={(event) => onChange(event.target.value)}
          onKeyDown={(event) => {
            if (menu.open && (event.key === "Escape" || event.key === "Tab")) {
              event.preventDefault();
              menu.close();
              return;
            }
            if (
              event.key === "ArrowUp" &&
              event.currentTarget.value === "" &&
              onEditLast
            ) {
              event.preventDefault();
              onEditLast();
            }
          }}
          onKeyUp={menu.refresh}
          onClick={menu.refresh}
          disabled={disabled}
          placeholder={placeholder}
          aria-label={placeholder}
        />
        <PromptInputFooter>
          <PromptInputTools>
            {attachments ? (
              <PromptInputActionMenu>
                <PromptInputActionMenuTrigger aria-label={t("attachments.add")} />
                <PromptInputActionMenuContent>
                  <PromptInputActionAddAttachments
                    label={t("attachments.add")}
                  />
                </PromptInputActionMenuContent>
              </PromptInputActionMenu>
            ) : null}
            <SpeechInput
              startLabel={t("composer.voiceStart")}
              stopLabel={t("composer.voiceStop")}
              onTranscript={(text, isFinal) => {
                if (!isFinal) return;
                const spoken = text.trim();
                if (!spoken) return;
                onChange(value ? `${value.replace(/\s+$/, "")} ${spoken}` : spoken);
              }}
            />
            {models.length > 1 && modelId && onModelChange ? (
              <PromptInputSelect
                value={modelId}
                onValueChange={(next) => {
                  if (typeof next === "string") onModelChange(next);
                }}
              >
                <PromptInputSelectTrigger
                  size="sm"
                  aria-label={t("model.label")}
                >
                  <PromptInputSelectValue />
                </PromptInputSelectTrigger>
                <PromptInputSelectContent>
                  {models.map((model) => (
                    <PromptInputSelectItem key={model.id} value={model.id}>
                      {model.label}
                    </PromptInputSelectItem>
                  ))}
                </PromptInputSelectContent>
              </PromptInputSelect>
            ) : null}
          </PromptInputTools>
          <PromptInputSubmit
            status={isStreaming ? "streaming" : uploading ? "submitted" : "ready"}
            label={isStreaming ? t("input.stop") : t("input.send")}
            disabled={
              !isStreaming && (disabled || uploading || !value.trim())
            }
            onClick={isStreaming ? onStop : undefined}
          />
        </PromptInputFooter>
      </PromptInput>
      <div className={compact ? "relative" : "relative mx-auto max-w-3xl"}>
        <ComposerMenu
          open={menu.open}
          options={menu.options}
          query={menu.query}
          onSelect={menu.select}
          emptyLabel={t("composer.noResults")}
        />
      </div>
      {compact ? null : (
        <p className="mx-auto mt-1 max-w-3xl px-1 text-xs text-muted-foreground">
          {t("input.hint")}
        </p>
      )}
    </div>
  );
}

"use client";

/**
 * Conversation header — the agent's name, the title with inline
 * rename, the consumer's `headerRight` slot, share, and delete.
 *
 * Below `lg` the sidebar is not on screen, so the header carries a
 * trigger that opens it in a sheet; from `lg` up the page renders the
 * sidebar as a column and the trigger is hidden.
 */

import { useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import {
  CheckIcon,
  PanelLeftIcon,
  PencilIcon,
  Trash2Icon,
  XIcon,
} from "lucide-react";
import { toast } from "sonner";

import { useRouter } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Sheet,
  SheetContent,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { Spinner } from "@/components/ui/spinner";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

import { deleteConversation, renameConversation } from "@/actions/chat";
import type { ConversationSummary } from "@/actions/chat";
import { chatConfig } from "@/lib/chat-config";
import { ConversationSidebar } from "./conversation-sidebar";
import { ShareDialog } from "./share-dialog";

interface ConversationHeaderProps {
  conversationId: string;
  title: string | null;
  conversations: ConversationSummary[];
}

export function ConversationHeader({
  conversationId,
  title,
  conversations,
}: ConversationHeaderProps) {
  const t = useTranslations("chat");
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [isEditing, setIsEditing] = useState(false);
  const [draftTitle, setDraftTitle] = useState(title ?? "");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const HeaderRight = chatConfig.headerRight;
  const agentName = chatConfig.agent?.name ?? t("agent.defaultName");
  const agentIcon = chatConfig.agent?.icon;

  function startEditing() {
    setDraftTitle(title ?? "");
    setIsEditing(true);
  }

  function commitRename() {
    const trimmed = draftTitle.trim();
    setIsEditing(false);
    if (!trimmed || trimmed === title) return;

    startTransition(async () => {
      const result = await renameConversation(conversationId, trimmed);
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      router.refresh();
    });
  }

  function handleDelete() {
    startTransition(async () => {
      const result = await deleteConversation(conversationId);
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      router.push("/chat");
    });
  }

  return (
    <header className="flex items-center justify-between gap-2 border-b px-4 py-3">
      <div className="flex min-w-0 flex-1 items-center gap-1">
        {/* Below `lg` this is the only way to reach history; at `lg`
            and up the page renders the sidebar as a column. */}
        <Sheet open={sidebarOpen} onOpenChange={setSidebarOpen}>
          <SheetTrigger
            render={
              <Button
                variant="ghost"
                size="icon-sm"
                className="mr-1 shrink-0 lg:hidden"
                aria-label={t("header.openHistory")}
              />
            }
          >
            <PanelLeftIcon />
          </SheetTrigger>
          <SheetContent side="left" className="w-72 p-0">
            <SheetTitle className="sr-only">{t("sidebar.label")}</SheetTitle>
            <ConversationSidebar
              conversations={conversations}
              activeId={conversationId}
              onNavigate={() => setSidebarOpen(false)}
              className="flex h-full w-full border-r-0"
            />
          </SheetContent>
        </Sheet>

        <span className="mr-1 flex shrink-0 items-center gap-1 text-xs text-muted-foreground">
          {agentIcon ? <span aria-hidden>{agentIcon}</span> : null}
          <span className="max-w-24 truncate">{agentName}</span>
        </span>
        {isEditing ? (
          <>
            <Input
              autoFocus
              value={draftTitle}
              onChange={(event) => setDraftTitle(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Enter") commitRename();
                if (event.key === "Escape") setIsEditing(false);
              }}
              className="h-8 max-w-xs"
            />
            <Button
              size="icon-sm"
              variant="ghost"
              className="shrink-0"
              onClick={commitRename}
              aria-label={t("header.renameSave")}
            >
              <CheckIcon />
            </Button>
            <Button
              size="icon-sm"
              variant="ghost"
              className="shrink-0"
              onClick={() => setIsEditing(false)}
              aria-label={t("header.renameCancel")}
            >
              <XIcon />
            </Button>
          </>
        ) : (
          <>
            <h1 className="truncate text-sm font-medium">
              {title || t("header.newChatTitle")}
            </h1>
            <Button
              size="icon-xs"
              variant="ghost"
              className="shrink-0"
              onClick={startEditing}
              aria-label={t("header.renameEdit")}
            >
              <PencilIcon />
            </Button>
          </>
        )}
      </div>

      <div className="flex shrink-0 items-center gap-2">
        {HeaderRight ? <HeaderRight conversationId={conversationId} /> : null}

        <ShareDialog conversationId={conversationId} />

        {/* Confirmed: deleting a conversation is unrecoverable. */}
        <AlertDialog>
          <AlertDialogTrigger
            render={
              <Button
                variant="ghost"
                size="icon-sm"
                className="text-muted-foreground hover:text-destructive"
                disabled={isPending}
                aria-label={t("header.delete")}
              />
            }
          >
            {isPending ? <Spinner /> : <Trash2Icon />}
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>{t("deleteDialog.title")}</AlertDialogTitle>
              <AlertDialogDescription>
                {t("deleteDialog.description")}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>{t("deleteDialog.cancel")}</AlertDialogCancel>
              <AlertDialogAction onClick={handleDelete}>
                {t("deleteDialog.confirm")}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>
    </header>
  );
}

"use client";

/**
 * Conversation history beside the chat — grouped by recency, pinned
 * on top, filterable, with everything a row needs: open, rename in
 * place, pin, delete with a few seconds to change your mind.
 *
 * From `lg` up the page renders it as a fixed column; below, the
 * header opens the same component in a sheet. Keyboard: arrows move
 * between rows, Enter opens, F2 renames, Delete deletes.
 *
 * Filtering is client-side over what the server already sent. That is
 * honest for the sizes this list actually reaches; a workspace with
 * thousands of conversations wants a server-side search action, and
 * this component's props are shaped so adding one later replaces the
 * filter without touching the layout.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  MessageSquareIcon,
  MoreHorizontalIcon,
  PencilIcon,
  PinIcon,
  PinOffIcon,
  PlusIcon,
  SearchIcon,
  Trash2Icon,
} from "lucide-react";
import { useTranslations } from "next-intl";
import { toast } from "sonner";

import { Link, useRouter } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Empty, EmptyDescription } from "@/components/ui/empty";
import { Input } from "@/components/ui/input";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";
import { cn } from "@/lib/utils";
import {
  deleteConversation,
  renameConversation,
  setConversationPinned,
  type ConversationSummary,
} from "@/actions/chat";

interface ConversationSidebarProps {
  conversations: ConversationSummary[];
  /** The conversation on screen, highlighted and never filtered out. */
  activeId: string;
  /** Called after a row is opened — a sheet closes itself. */
  onNavigate?: () => void;
  className?: string;
}

type Bucket = "pinned" | "today" | "yesterday" | "week" | "month" | "older";

const BUCKET_ORDER: Bucket[] = [
  "pinned",
  "today",
  "yesterday",
  "week",
  "month",
  "older",
];

const UNDO_MS = 5000;

function bucketFor(conversation: ConversationSummary, now: number): Bucket {
  if (conversation.pinned) return "pinned";
  const ageMs = now - new Date(conversation.updatedAt).getTime();
  const day = 24 * 60 * 60 * 1000;
  if (ageMs < day) return "today";
  if (ageMs < 2 * day) return "yesterday";
  if (ageMs < 7 * day) return "week";
  if (ageMs < 30 * day) return "month";
  return "older";
}

export function ConversationSidebar({
  conversations,
  activeId,
  onNavigate,
  className,
}: ConversationSidebarProps) {
  const t = useTranslations("chat");
  const router = useRouter();
  const [query, setQuery] = useState("");
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [draft, setDraft] = useState("");
  const [hidden, setHidden] = useState<Set<string>>(new Set());
  const [titles, setTitles] = useState<Record<string, string>>({});
  const [pins, setPins] = useState<Record<string, boolean>>({});
  const listRef = useRef<HTMLElement>(null);
  const timers = useRef(new Map<string, ReturnType<typeof setTimeout>>());

  useEffect(
    () => () => {
      for (const timer of timers.current.values()) clearTimeout(timer);
    },
    []
  );

  const rows = useMemo(
    () =>
      conversations
        .filter((conversation) => !hidden.has(conversation.id))
        .map((conversation) => ({
          ...conversation,
          title: titles[conversation.id] ?? conversation.title,
          pinned: pins[conversation.id] ?? conversation.pinned,
        })),
    [conversations, hidden, titles, pins]
  );

  const grouped = useMemo(() => {
    const needle = query.trim().toLowerCase();
    // `Date.now()` inside the memo, not during render, keeps the
    // bucket boundaries stable for a given filter pass.
    const now = Date.now();
    const buckets = new Map<Bucket, typeof rows>();
    for (const conversation of rows) {
      if (
        needle &&
        conversation.id !== activeId &&
        !(conversation.title ?? "").toLowerCase().includes(needle)
      ) {
        continue;
      }
      const bucket = bucketFor(conversation, now);
      buckets.set(bucket, [...(buckets.get(bucket) ?? []), conversation]);
    }
    return buckets;
  }, [rows, query, activeId]);

  const empty = BUCKET_ORDER.every((bucket) => !grouped.get(bucket)?.length);

  function startRename(conversation: ConversationSummary) {
    setRenamingId(conversation.id);
    setDraft(titles[conversation.id] ?? conversation.title ?? "");
  }

  function commitRename(id: string) {
    const trimmed = draft.trim();
    setRenamingId(null);
    if (!trimmed) return;
    setTitles((previous) => ({ ...previous, [id]: trimmed }));
    void renameConversation(id, trimmed).then((result) => {
      if (!result.success) {
        setTitles((previous) => {
          const next = { ...previous };
          delete next[id];
          return next;
        });
        toast.error(result.error);
      } else {
        router.refresh();
      }
    });
  }

  function togglePin(conversation: ConversationSummary) {
    const next = !(pins[conversation.id] ?? conversation.pinned);
    setPins((previous) => ({ ...previous, [conversation.id]: next }));
    void setConversationPinned(conversation.id, next).then((result) => {
      if (!result.success) {
        setPins((previous) => ({ ...previous, [conversation.id]: !next }));
        toast.error(result.error);
      }
    });
  }

  const remove = useCallback(
    (id: string) => {
      setHidden((previous) => new Set(previous).add(id));
      const timer = setTimeout(() => {
        timers.current.delete(id);
        void deleteConversation(id).then((result) => {
          if (!result.success) {
            setHidden((previous) => {
              const next = new Set(previous);
              next.delete(id);
              return next;
            });
            toast.error(result.error);
            return;
          }
          if (id === activeId) router.push("/chat");
          else router.refresh();
        });
      }, UNDO_MS);
      timers.current.set(id, timer);
      toast(t("sidebar.deleted"), {
        duration: UNDO_MS,
        action: {
          label: t("sidebar.undo"),
          onClick: () => {
            const pendingTimer = timers.current.get(id);
            if (pendingTimer) clearTimeout(pendingTimer);
            timers.current.delete(id);
            setHidden((previous) => {
              const next = new Set(previous);
              next.delete(id);
              return next;
            });
          },
        },
      });
    },
    [activeId, router, t]
  );

  // Roving focus over the rows; the row's own link handles Enter.
  function onListKeyDown(event: React.KeyboardEvent<HTMLElement>) {
    const target = event.target as HTMLElement;
    const row = target.closest<HTMLElement>("[data-conversation]");
    if (!row || renamingId) return;
    const links = Array.from(
      listRef.current?.querySelectorAll<HTMLElement>("[data-conversation]") ?? []
    );
    const index = links.indexOf(row);
    if (event.key === "ArrowDown") {
      event.preventDefault();
      links[Math.min(index + 1, links.length - 1)]?.focus();
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      links[Math.max(index - 1, 0)]?.focus();
    } else if (event.key === "F2") {
      event.preventDefault();
      const conversation = rows.find((c) => c.id === row.dataset.conversation);
      if (conversation) startRename(conversation);
    } else if (event.key === "Delete") {
      event.preventDefault();
      if (row.dataset.conversation) remove(row.dataset.conversation);
    }
  }

  return (
    <aside className={cn("w-64 shrink-0 flex-col border-r", className)}>
      <div className="space-y-2 border-b p-3">
        <Button
          size="sm"
          className="w-full justify-start gap-2"
          render={<Link href="/chat" onClick={onNavigate} />}
          nativeButton={false}
        >
          <PlusIcon data-icon="inline-start" />
          {t("header.newChat")}
        </Button>

        <InputGroup>
          <InputGroupAddon>
            <SearchIcon />
          </InputGroupAddon>
          <InputGroupInput
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder={t("sidebar.searchPlaceholder")}
            aria-label={t("sidebar.searchPlaceholder")}
          />
        </InputGroup>
      </div>

      <nav
        ref={listRef}
        aria-label={t("sidebar.label")}
        className="flex-1 overflow-y-auto px-2 py-3"
        onKeyDown={onListKeyDown}
      >
        {empty ? (
          <Empty className="p-4">
            <EmptyDescription>
              {query ? t("sidebar.noMatches") : t("header.historyEmpty")}
            </EmptyDescription>
          </Empty>
        ) : (
          BUCKET_ORDER.map((bucket) => {
            const items = grouped.get(bucket);
            if (!items?.length) return null;
            return (
              <div key={bucket} className="mb-4">
                <p className="px-2 pb-1 text-xs font-medium text-muted-foreground">
                  {t(`sidebar.groups.${bucket}`)}
                </p>
                <ul>
                  {items.map((conversation) => {
                    const isActive = conversation.id === activeId;
                    const label =
                      conversation.title ?? t("header.historyUntitled");
                    if (renamingId === conversation.id) {
                      return (
                        <li key={conversation.id} className="px-1 py-0.5">
                          <Input
                            autoFocus
                            value={draft}
                            onChange={(event) => setDraft(event.target.value)}
                            onBlur={() => commitRename(conversation.id)}
                            onKeyDown={(event) => {
                              if (event.key === "Enter") {
                                event.preventDefault();
                                commitRename(conversation.id);
                              }
                              if (event.key === "Escape") setRenamingId(null);
                            }}
                            className="h-8"
                            aria-label={t("sidebar.rename")}
                          />
                        </li>
                      );
                    }
                    return (
                      <li
                        key={conversation.id}
                        className={cn(
                          "group/row flex items-center rounded-md",
                          isActive ? "bg-accent" : "hover:bg-accent/50"
                        )}
                      >
                        <Link
                          href={`/chat/${conversation.id}`}
                          data-conversation={conversation.id}
                          aria-current={isActive ? "page" : undefined}
                          onClick={onNavigate}
                          onDoubleClick={(event) => {
                            event.preventDefault();
                            startRename(conversation);
                          }}
                          className={cn(
                            "flex min-w-0 flex-1 items-center gap-2 rounded-md px-2 py-1.5 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring",
                            isActive && "font-medium"
                          )}
                          title={label}
                        >
                          {conversation.pinned ? (
                            <PinIcon
                              className="size-3.5 shrink-0 text-muted-foreground"
                              aria-hidden
                            />
                          ) : (
                            <MessageSquareIcon
                              className="size-3.5 shrink-0 text-muted-foreground"
                              aria-hidden
                            />
                          )}
                          <span className="truncate">{label}</span>
                        </Link>
                        <DropdownMenu>
                          <DropdownMenuTrigger
                            render={
                              <Button
                                variant="ghost"
                                size="icon-xs"
                                className="mr-1 shrink-0 text-muted-foreground opacity-0 group-hover/row:opacity-100 focus-visible:opacity-100 data-popup-open:opacity-100"
                                aria-label={t("sidebar.menu")}
                              />
                            }
                          >
                            <MoreHorizontalIcon />
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem
                              onClick={() => togglePin(conversation)}
                            >
                              {conversation.pinned ? (
                                <PinOffIcon />
                              ) : (
                                <PinIcon />
                              )}
                              {conversation.pinned
                                ? t("sidebar.unpin")
                                : t("sidebar.pin")}
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => startRename(conversation)}
                            >
                              <PencilIcon />
                              {t("sidebar.rename")}
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              variant="destructive"
                              onClick={() => remove(conversation.id)}
                            >
                              <Trash2Icon />
                              {t("sidebar.delete")}
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </li>
                    );
                  })}
                </ul>
              </div>
            );
          })
        )}
      </nav>

      <p className="border-t px-3 py-2 text-xs text-muted-foreground">
        {t("sidebar.count", { count: rows.length })}
      </p>
    </aside>
  );
}

"use client";

/**
 * Publish a conversation as a read-only page anyone with the link can
 * open, and stop sharing it again. What the page shows is decided
 * server-side (`sanitizeForShare` in `@intelligo-dev/chat`): the
 * reader's reasoning, tool details and attachments never leave.
 */

import { useEffect, useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import { Share2Icon } from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { CopyButton } from "@/components/ui/copy-button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Spinner } from "@/components/ui/spinner";
import { getShareState, setConversationShared } from "@/actions/chat";

interface ShareDialogProps {
  conversationId: string;
}

export function ShareDialog({ conversationId }: ShareDialogProps) {
  const t = useTranslations("chat");
  const [open, setOpen] = useState(false);
  const [shared, setShared] = useState<boolean | null>(null);
  const [isPending, startTransition] = useTransition();

  useEffect(() => {
    if (!open) return;
    void getShareState(conversationId).then((result) => {
      setShared(result.success ? result.data.shared : false);
    });
  }, [open, conversationId]);

  const url =
    typeof window === "undefined"
      ? ""
      : `${window.location.origin}/share/${conversationId}`;

  function toggle(next: boolean) {
    startTransition(async () => {
      const result = await setConversationShared(conversationId, next);
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      setShared(next);
    });
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger
        render={
          <Button
            variant="ghost"
            size="icon-sm"
            className="text-muted-foreground"
            aria-label={t("header.share")}
          />
        }
      >
        <Share2Icon />
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{t("share.title")}</DialogTitle>
          <DialogDescription>{t("share.description")}</DialogDescription>
        </DialogHeader>
        {shared === null ? (
          <Spinner />
        ) : shared ? (
          <div className="flex items-center gap-2">
            <Input readOnly value={url} aria-label={t("share.copyLink")} />
            <CopyButton
              value={url}
              label={t("share.copyLink")}
              copiedLabel={t("share.linkCopied")}
              onCopyError={() => toast.error(t("actions.copyFailed"))}
              size="sm"
              variant="outline"
            >
              {t("share.copyLink")}
            </CopyButton>
          </div>
        ) : null}
        <DialogFooter>
          {shared ? (
            <Button
              variant="outline"
              type="button"
              disabled={isPending}
              aria-busy={isPending || undefined}
              onClick={() => toggle(false)}
            >
              {isPending ? <Spinner data-icon="inline-start" /> : null}
              {t("share.disable")}
            </Button>
          ) : (
            <Button
              type="button"
              disabled={isPending || shared === null}
              aria-busy={isPending || undefined}
              onClick={() => toggle(true)}
            >
              {isPending ? <Spinner data-icon="inline-start" /> : null}
              {t("share.enable")}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

/**
 * Tells the reader about their credit before they spend a message on
 * finding out.
 *
 * Two states, and both matter:
 *
 *   - **blocked** — the next turn will be refused. Server-rendered
 *     from `getChatQuotaState()`, or seeded from the route's own 402
 *     when the balance runs out mid-conversation.
 *   - **running low** — allowed, but one more turn would take most of
 *     what is left. A warning nobody asked for beats a refusal nobody
 *     expected.
 *
 * Copy lives in this item's `chat` namespace, not in props. The
 * product-side version of this component took a `CreditBannerStrings`
 * object with English defaults, because it lived in a package and a
 * package cannot reach next-intl — which also meant its defaults
 * hardcoded a currency symbol and a language. An item has no such
 * problem (ADR-0010).
 *
 * Amounts are credits, not money. That is the unit the balance and the
 * estimate are both in; rendering it as currency would need an
 * exchange rate this component has no business choosing.
 */

import { AlertTriangleIcon, SparklesIcon } from "lucide-react";
import { useFormatter, useTranslations } from "next-intl";

import type { ChatQuotaState } from "@intelligo-dev/chat/client";

import {
  Alert,
  AlertAction,
  AlertDescription,
  AlertTitle,
} from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Link } from "@/i18n/navigation";

/**
 * What the page opened with, read by `getChatQuotaState()`. The shape
 * is the transport's (`@intelligo-dev/chat/client`, which imports
 * nothing, so a client component can read it without pulling a server
 * module into its graph). Re-exported so `lib/chat-quota.ts` and the
 * page name it from the component that renders it.
 */
export type { ChatQuotaState };

/**
 * A refusal that arrived from the route mid-conversation, rather than
 * from the server render.
 */
export type ChatBlock = {
  code: string;
  message: string;
};

interface CreditStatusBannerProps {
  quotaState: ChatQuotaState | null;
  block: ChatBlock | null;
}

export function CreditStatusBanner({
  quotaState,
  block,
}: CreditStatusBannerProps) {
  const t = useTranslations("chat");
  const format = useFormatter();

  // A block from the route wins: it is the newer fact. The
  // server-rendered state is what the page opened with, and the reader
  // may have spent their last credits since.
  const refusal: ChatBlock | null =
    block ??
    (quotaState && !quotaState.allowed
      ? { code: quotaState.code ?? "", message: quotaState.reason ?? "" }
      : null);

  if (refusal) {
    return (
      <Alert
        variant="destructive"
        data-testid="credit-status-banner"
        className="mx-auto mb-2 w-full max-w-3xl"
      >
        <AlertTriangleIcon />
        <AlertTitle>
          {refusal.code === "insufficient_credits" ||
          refusal.code === "allowance_depleted"
            ? t("creditBanner.outOfCredits")
            : t("creditBanner.upgradeRequired")}
        </AlertTitle>
        {refusal.message ? (
          <AlertDescription>{refusal.message}</AlertDescription>
        ) : null}
        <AlertAction>
          <Button
            size="sm"
            variant="destructive"
            render={<Link href={quotaState?.upgradeHref ?? "/pricing"} />}
            nativeButton={false}
          >
            {t("creditBanner.upgrade")}
          </Button>
        </AlertAction>
      </Alert>
    );
  }

  // "Running low" is one turn's worth of headroom, not a percentage: a
  // share of a large allowance can still be plenty, while twice the
  // estimate is exactly the point where the next message might be the
  // last one.
  const runningLow =
    quotaState !== null &&
    quotaState.allowed &&
    quotaState.estimated > 0 &&
    quotaState.remaining < quotaState.estimated * 2;

  if (!runningLow || !quotaState) return null;

  return (
    <Alert
      role="status"
      data-testid="credit-status-warning"
      className="mx-auto mb-2 w-full max-w-3xl border-warning/30 bg-warning/10 text-warning"
    >
      <SparklesIcon />
      <AlertTitle>
        {t("creditBanner.runningLow", {
          count: quotaState.remaining,
          amount: format.number(quotaState.remaining),
        })}
      </AlertTitle>
      <AlertAction>
        <Button
          size="xs"
          variant="ghost"
          className="text-warning hover:text-warning"
          render={<Link href={quotaState.upgradeHref} />}
          nativeButton={false}
        >
          {t("creditBanner.topUp")}
        </Button>
      </AlertAction>
    </Alert>
  );
}
